'use client';

// Ported from the artifact's _axInit/_axDispose (project/Main.dc.html,
// card index 3 -- "Scaling enterprise sales" -> AXA). The four edge texts
// (.ax-top/.ax-right/.ax-bottom/.ax-left) loop continuously along their
// own axis while the card is hovered, and glide back to their poster pose
// over 1s when the pointer leaves -- not CSS, because the glide-back needs
// a physically correct "ease out, land exactly on a loop-length multiple"
// curve computed from each lane's live position/velocity at the moment the
// pointer left. A plain CSS transition can't resume mid-loop from an
// arbitrary point with matching velocity, hence the imperative rAF loop
// below (kept byte-for-byte faithful to the original's math).
//
// The artifact drives this through document-level pointerover/pointerout
// delegation (pointerover/out bubble, unlike pointerenter/leave) plus a
// periodic elementFromPoint re-check, to catch cases a plain hover
// listener can miss: the carousel spinning a card out from under a still
// cursor, or a touch pointer lifting without a clean "out" event. That's
// preserved here nearly verbatim -- the only real change from the
// original is scoping it to this one component instance via a ref/closure
// instead of a WeakMap keyed across every .ax-card on the page (this
// portfolio only ever renders one AXA card, unlike the artifact's canvas
// runtime which had to handle N instances generically).

import { useEffect, useRef } from 'react';
import { prefersReducedMotion } from '@/lib/cardTransition';

const LANES = [
  { cls: 'ax-top', dx: 1, dy: 0, P: 220, v: 40 },
  { cls: 'ax-right', dx: 0, dy: 1, P: 590, v: 55 },
  { cls: 'ax-bottom', dx: -1, dy: 0, P: 590, v: 55 },
  { cls: 'ax-left', dx: 0, dy: -1, P: 300, v: 40 },
];
const SETTLE_MS = 1000; // time to glide back to the original position after hover ends
const ACCEL_TAU = 0.45; // seconds, how quickly the slide speeds up when hover starts

