export default function AXACard() {
  const wrapRef = useRef(null);

  useEffect(() => {
    const wrap = wrapRef.current;
    if (!wrap) return undefined;
    const card = wrap.querySelector('.ax-card');
    const face = wrap.closest('.card-face');
    if (!card || !face) return undefined;

    const reduce = prefersReducedMotion();
    const lanes = LANES.map((c) => {
      const el = card.querySelector('.' + c.cls);
      return el ? { el, dx: c.dx, dy: c.dy, P: c.P, v: c.v, pos: 0, vel: 0, plan: null } : null;
    }).filter(Boolean);
    if (lanes.length === 0) return undefined;

    const ptr = { x: -1, y: -1, gone: true };
    const st = { mode: 'idle', raf: 0, last: 0, lastCheck: 0 };

    const apply = (L) => {
      const off = ((L.pos % L.P) + L.P) % L.P;
      L.el.style.translate = `${L.dx * off}px ${L.dy * off}px`;
    };
    const makePlan = (L, now) => {
      const T = SETTLE_MS / 1000;
      const mod = ((L.pos % L.P) + L.P) % L.P;
      const D = mod < L.P / 2 ? -mod : L.P - mod;
      return { t0: now, T, D, v0: L.vel, pos0: L.pos };
    };
    const beginSettle = (now) => {
      st.mode = 'settle';
      lanes.forEach((L) => {
        L.plan = makePlan(L, now);
      });
    };
    const isOver = () => {
      if (ptr.gone) return false;
      const el = document.elementFromPoint(ptr.x, ptr.y);
      return !!(el && face.contains(el));
    };
    const frame = (now) => {
      if (st.mode === 'run' && now - st.lastCheck > 80) {
        st.lastCheck = now;
        if (!isOver()) beginSettle(now);
      }
      const dt = Math.min(0.05, Math.max(0, (now - st.last) / 1000));
      st.last = now;
      let active = false;
      lanes.forEach((L) => {
        if (st.mode === 'run') {
          L.vel += (L.v - L.vel) * (1 - Math.exp(-dt / ACCEL_TAU));
          L.pos += L.vel * dt;
          active = true;
        } else if (L.plan) {
          const p = L.plan;
          const u = Math.min(1, (now - p.t0) / 1000 / p.T);
          const a = p.v0 * p.T;
          L.pos = p.pos0 + (u * u * u - 2 * u * u + u) * a + (3 * u * u - 2 * u * u * u) * p.D;
          L.vel = u < 1 ? ((3 * u * u - 4 * u + 1) * a + (6 * u - 6 * u * u) * p.D) / p.T : 0;
          if (u < 1) {
            active = true;
          } else {
            L.plan = null;
            L.pos = 0;
            L.vel = 0;
          }
        }
        apply(L);
      });
      st.raf = 0;
      if (active) {
        st.raf = requestAnimationFrame(frame);
      } else {
        st.mode = 'idle';
      }
      if (typeof window !== 'undefined') {
        window.__axaFrameLog = window.__axaFrameLog || [];
        if (window.__axaFrameLog.length < 20) {
          window.__axaFrameLog.push({ mode: st.mode, active, pos0: lanes[0].pos, translate0: lanes[0].el.style.translate });
        }
      }
    };
    const kick = () => {
      if (typeof window !== 'undefined') {
        window.__axaKickLog = window.__axaKickLog || [];
        window.__axaKickLog.push({ rafWasTruthy: !!st.raf, rafValue: st.raf });
      }
      if (st.raf) return;
      st.last = performance.now();
      st.raf = requestAnimationFrame(frame);
    };
    // Only react to pointer events on THIS card's own face -- the artifact's
    // version looks this up generically (any .card-face under the event)
    // since one delegated listener served every ax-card on the page; here
    // there's only ever one, so we just filter for a match.
    const faceOf = (e) => {
      const target = e.target && e.target.closest ? e.target.closest('.card-face') : null;
      if (target !== face) return null;
      if (e.relatedTarget && face.contains(e.relatedTarget)) return null;
      return card;
    };
    const onOver = (e) => {
      ptr.x = e.clientX;
      ptr.y = e.clientY;
      ptr.gone = false;
      const matched = faceOf(e);
      if (typeof window !== 'undefined') {
        window.__axaDebug = window.__axaDebug || [];
        window.__axaDebug.push({ event: 'over', matched: !!matched, reduce, lanesCount: lanes.length });
      }
      if (!matched || reduce) return;
      st.mode = 'run';
      st.lastCheck = performance.now();
      lanes.forEach((L) => {
        L.plan = null;
      });
      kick();
    };
    const onOut = (e) => {
      if (!faceOf(e) || reduce) return;
      if (st.mode !== 'run') return;
      beginSettle(performance.now());
      kick();
    };
    const onMove = (e) => {
      ptr.x = e.clientX;
      ptr.y = e.clientY;
      ptr.gone = false;
    };
    // finger lifted / pointer cancelled / left the window: nothing is hovering any more
    const onGone = (e) => {
      if (!e || e.type !== 'pointerup' || e.pointerType !== 'mouse') ptr.gone = true;
    };

    document.addEventListener('pointerover', onOver);
    document.addEventListener('pointerout', onOut);
    document.addEventListener('pointermove', onMove, { passive: true });
    document.addEventListener('pointerup', onGone);
    document.addEventListener('pointercancel', onGone);
    document.documentElement.addEventListener('mouseleave', onGone);
    window.addEventListener('blur', onGone);

    return () => {
      document.removeEventListener('pointerover', onOver);
      document.removeEventListener('pointerout', onOut);
      document.removeEventListener('pointermove', onMove);
      document.removeEventListener('pointerup', onGone);
      document.removeEventListener('pointercancel', onGone);
      document.documentElement.removeEventListener('mouseleave', onGone);
      window.removeEventListener('blur', onGone);
      if (st.raf) cancelAnimationFrame(st.raf);
    };
  }, []);

  return <div className="ax-card-wrap" ref={wrapRef} dangerouslySetInnerHTML={{ __html: AXA_SVG }} />;
}
